import {hearButton} from './play-media.mjs';
import {lanternCases} from './lantern-line-content.mjs';
import {lanternView,startLantern,recoverLantern,editLantern,supportLantern,checkLantern,keepLantern} from './lantern-line-core.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=['place','compare','kept'],titles={place:'Place our lanterns',compare:'Read our lantern line',kept:'Our kept version'};
const button=(label,attrs,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const description=s=>s.source.markers.map(m=>s.indices[m.id]===null?`${m.label}: no position yet.`:`${m.label}: ${s.indices[m.id]} ${s.indices[m.id]===1?'part':'parts'} of ${m.denominator}, or ${s.indices[m.id]}/${m.denominator} of this whole walk.`).join(' ');
function line(s){
 const markers=s.source.markers,selected=markers.find(m=>m.id===s.guide),den=selected?.denominator||1;
 const ticks=Array.from({length:den+1},(_,i)=>`<path d="M${30+i*300/den} 58v14" stroke="#507360"/>`).join('');
 const points=markers.map((m,i)=>{const n=s.indices[m.id];if(n===null)return '';const x=30+n*300/m.denominator,y=i===0?35:95,style=i===0?'#b67d24':'#477d97';return `<g data-lantern-point="${esc(m.id)}" data-tick="${12*n/m.denominator}"><path d="M${x} ${y}V65" stroke="${style}" stroke-width="2"/>${m.shape==='circle'?`<circle cx="${x}" cy="${y}" r="7" fill="${style}" stroke="#254839"/>`:`<path d="M${x} ${y-8}l8 15h-16Z" fill="${style}" stroke="#254839"/>`}<text x="${x}" y="${i===0?17:120}" text-anchor="middle">${i===0?'A':'B'}</text></g>`;}).join('');
 return `<figure class="lantern-figure"><svg viewBox="0 0 360 145" role="img" aria-label="${esc(description(s))}"><path d="M30 65H330" stroke="#254839" stroke-width="3"/>${ticks}${points}<text x="30" y="140" text-anchor="middle">0</text><text x="330" y="140" text-anchor="middle">1</text></svg><figcaption><p>Gate 0 to Arch 1 is one whole walk. Compare horizontal positions; label height does not change a stop.</p><p>${esc(description(s))}</p><p class="tiny">A: ${esc(markers[0].label)} · B: ${esc(markers[1].label)}. ${selected?`${esc(selected.label)} guides divide the same whole into ${selected.denominator} equal parts.`:'Only the ends are marked. Part guides are optional help.'}</p></figcaption></figure>`;
}
const requested=s=>`<ul class="lantern-requests">${s.markers.map((m,i)=>`<li><strong>${i===0?'A':'B'}: ${esc(m.label)}</strong> · requested stop ${m.numerator}/${m.denominator}</li>`).join('')}</ul>`;
function saved(s){return `<p>${esc(s.source.title)}</p>${requested(s.source)}<p>${esc(description(s))}</p><p>Order choice: ${esc(s.choice===null?'none':s.choice==='same'?'same point':s.source.markers[s.choice==='first'?0:1].label)}. Support: ${esc(s.support.join(', ')||'none recorded')}. Pictured practice.</p>`;}
function chooser(v){return `<details class="lantern-chooser" ${v.work?'':'open'}><summary>Choose any walk</summary>${lanternCases.map(s=>{const bad=v.unreadable.some(x=>x.id===s.id),old=v.readable.some(x=>x.id===s.id);return `<article><h3>${esc(s.title)}</h3>${requested(s)}${bad?'<p>This earlier walk is unreadable and remains in your download. Other walks stay open.</p>':button(old?'Return to this walk':'Start this walk',`data-lantern-start="${s.id}"`)}</article>`;}).join('')}${v.readable.filter(x=>!lanternCases.some(s=>s.id===x.id)).map(x=>`<article><h3>${esc(x.work.source.title)}</h3>${button('Resume this earlier walk',`data-lantern-start="${esc(x.id)}"`)}</article>`).join('')}</details>`;}
function example(w){const s={source:{...w.source,markers:w.source.markers.map((m,i)=>({...m,...w.source.example[i===0?'first':'second']}))},indices:Object.fromEntries(w.source.markers.map((m,i)=>[m.id,w.source.example[i===0?'first':'second'].numerator])),guide:null};return `<details class="lantern-example"><summary>A separate worked example</summary><p>Your own stops stay where you left them.</p>${line(s)}${w.source.copy.exampleSteps.map((text,i)=>`<details><summary>Example step ${i+1}</summary><p>${esc(text)}</p></details>`).join('')}</details>`;}
function narration(v){const w=v.work;if(!w)return 'Choose any lantern walk. Each request is open.';if(w.page==='kept')return `${titles.kept}. `+(v.kept?description(v.kept.snapshot):'Nothing is kept for this walk yet. Incomplete work is welcome.');return `${titles[w.page]}. ${w.page==='place'?w.source.copy.intro:w.source.copy.comparison} `+w.source.markers.map(m=>`${m.label} is requested at ${m.numerator}/${m.denominator}.`).join(' ')+' '+description(w);}
export function lanternEntry(){return '<section class="resume-strip lantern-entry"><div><h2>Two lanterns, one walk</h2><p>Place two fraction stops, then compare the line you made.</p><a class="secondary" href="#numbers/lanterns">Visit Lantern Line</a></div></section>';}
export function lanternPage(state){
 const v=lanternView(state),head='<section class="lantern-sheet" data-lantern-root><a class="back" href="#numbers">Back to Number Garden</a>',status='<p id="lantern-status" role="status" tabindex="-1"></p>';
 if(v.status==='recovery')return head+'<h1 id="lantern-title" tabindex="-1">Lantern Line</h1><p>This earlier lantern notebook cannot be opened here. It remains in your download; other games stay open.</p>'+button('Start a separate lantern notebook','data-lantern-recover')+status+'<a class="secondary" href="#notes">Grown-up notes and download</a></section>';
 if(!v.work)return head+'<h1 id="lantern-title" tabindex="-1">Lantern Line</h1><p>The lantern walk needs two stops along one whole route. Choose a walk to place and compare them.</p>'+chooser(v)+status+'<a class="secondary" href="#notes">Grown-up notes and download</a>'+(v.unreadable.length?button('Start a separate lantern notebook','data-lantern-recover'):'')+'</section>';
 const w=v.work,s=w.source,index=pages.indexOf(w.page);
 let work='';
 if(w.page==='place')work=s.markers.map(m=>{const n=w.indices[m.id];return `<fieldset><legend>${esc(m.label)} · ${m.denominator} equal parts in the whole</legend><p>${n===null?'No marker yet.':`Current step count: ${n} of ${m.denominator}.`}</p><div class="lantern-actions">${button(`Start ${m.label} at zero`,`data-lantern-zero="${esc(m.id)}"`)}${button('Back one part',`data-lantern-move="${esc(m.id)}" data-delta="-1" aria-label="Back one part for ${esc(m.label)}" ${n===null||n===0?'disabled':''}`)}${button('Forward one part',`data-lantern-move="${esc(m.id)}" data-delta="1" aria-label="Forward one part for ${esc(m.label)}" ${n===null||n===m.denominator?'disabled':''}`)}</div></fieldset>`;}).join('')+`<fieldset><legend>Optional equal-part guides</legend><div class="lantern-actions">${s.markers.map(m=>button(`Show ${m.label}'s equal parts`,`data-lantern-guide="${esc(m.id)}" aria-pressed="${w.guide===m.id}"`)).join('')}${button('Hide part guides','data-lantern-guide=""')}</div></fieldset>`;
 if(w.page==='compare')work=`<fieldset><legend>${esc(s.copy.comparison)}</legend><div class="lantern-actions">${[['first',s.markers[0].label],['same','Same point'],['second',s.markers[1].label]].map(([value,label])=>button(label,`data-lantern-choice="${value}" aria-pressed="${w.choice===value}"`)).join('')}${button('Leave order blank','data-lantern-choice=""')}</div></fieldset>${button('Check this line','data-lantern-check',true)}${v.feedback?`<p class="feedback" id="lantern-feedback" tabindex="-1">${esc(v.feedback.feedback)}</p>`:''}${v.readableChecks.length>=4?'<p class="tiny">New checks replace the oldest of the four recent readable checks. The kept copy stays. Download notes first to keep every check.</p>':''}`;
 if(w.page==='kept')work=v.kept?`<h2>Kept version</h2>${line(v.kept.snapshot)}${saved(v.kept.snapshot)}${v.kept.check?`<p>${esc(v.kept.check.feedback)}</p>`:'<p>This version was kept without a check.</p>'}`:v.keptUnreadable?'<p>Your earlier kept version is unreadable and stays in the download. It cannot be overwritten. A separate lantern notebook retains this whole notebook.</p>':'<p>No version is kept for this walk yet. Incomplete work is welcome.</p>';
 return head+`<p class="tiny">Lantern Line · ${index+1} of 3</p><h1 id="lantern-title" tabindex="-1">${titles[w.page]}</h1><h2>${esc(s.title)}</h2><p>${esc(w.page==='place'?s.copy.intro:w.page==='compare'?s.copy.comparison:'A kept copy stays frozen while you revise your current walk.')}</p>${requested(s)}${hearButton(narration(v),'Hear this turn')}${status}${w.page==='kept'?'':line(w)}${work}<details class="lantern-help"><summary>Help with this whole walk</summary><p>${esc(s.copy.help)}</p></details>${example(w)}${button('We worked together','data-lantern-together')}<nav class="lantern-actions" aria-label="Lantern Line turns">${index>0?button('Previous',`data-lantern-page="${pages[index-1]}"`):''}${index<2?button(`Next: ${titles[pages[index+1]].toLowerCase()}`,`data-lantern-page="${pages[index+1]}"`,true):''}${w.page==='compare'?button('Change the stops','data-lantern-page="place"'):''}</nav>${button(w.kept===null?'Keep this version':'Replace our kept version',`data-lantern-keep ${v.keptUnreadable?'disabled':''}`)}<details><summary>Latest four checks (${Math.min(4,v.readableChecks.length)})</summary><p>Earlier versions stay separate from the current line.</p>${v.readableChecks.slice(-4).map(c=>`<article><h3>Earlier check ${c.id}</h3>${saved(c.snapshot)}<p>${esc(c.feedback)}</p></article>`).join('')}${v.rawChecks.length?'<p>Some earlier checks are unreadable and remain in the download.</p>':''}</details>${chooser(v)}<details><summary>Grown-ups: practice and recovery</summary><p>This is a fictional model walk with supplied fraction requests and pictured support. Placement and reading the actual order are separate. No level or independent fraction fluency is inferred.</p><a class="secondary" href="#notes">Grown-up notes and download</a>${button('Start a separate lantern notebook','data-lantern-recover')}</details></section>`;
}
export function lanternNotes(state){const v=lanternView(state);if(v.status==='missing')return '';if(v.status==='recovery')return '<section><h2>Lantern Line</h2><p>Unreadable earlier notebook retained in the download.</p></section>';return `<details class="panel"><summary>Lantern Line: supplied pictured practice</summary>${v.readable.map(x=>`<section><h3>${esc(x.work.source.title)}</h3>${saved(x.work)}${x.readableChecks.slice(-4).map(c=>`<article><h4>Earlier check ${c.id}</h4>${saved(c.snapshot)}<p>${esc(c.feedback)}</p></article>`).join('')}${x.kept?`<h4>Kept copy</h4>${saved(x.kept.snapshot)}${x.kept.check?`<p>${esc(x.kept.check.feedback)}</p>`:''}`:''}${x.rawChecks.length||x.keptUnreadable?'<p>Some earlier work is unreadable; its full raw record remains in the download.</p>':''}</section>`).join('')}${v.unreadable.length?'<p>Some requests are unreadable; the other requests stay available and all raw records remain in the download.</p>':''}</details>`;}
export function bindLantern(state,{save,render,focus,canExport}){
 const root=document.querySelector('[data-lantern-root]');if(!root)return;const bound=lanternView(state).root?.current??null;
 const live=()=>document.contains(root)&&(lanternView(state).root?.current??null)===bound;
 const notice=text=>{if(!live())return;const n=root.querySelector('#lantern-status');if(n)n.textContent=text;};
 const refusal='This change could not fit safely. Earlier work is unchanged. Download notes, or start a separate explorer if the notebook is full.';
 const run=(fn,target,message)=>{if(!live())return false;if(!fn()){notice(refusal);return false;}save();render();if(message){const n=document.querySelector('#lantern-status');if(n)n.textContent=message;}if(target)focus(target);return true;};
 const confirm=(recover,fn)=>{if(!live())return;const d=document.createElement('dialog');d.innerHTML=`<div class="dialog-content"><h2>${recover?'Start a separate lantern notebook?':'Replace our kept version?'}</h2><p>${recover?'The entire earlier lantern notebook stays in your download, including its kept copies.':'This overwrites the one earlier kept version for this walk.'} Download notes first if you want another copy.</p><button class="secondary" data-lantern-cancel>Keep this page</button><button class="primary" data-lantern-confirm>Yes, continue</button></div>`;document.body.append(d);d.showModal();d.querySelector('[data-lantern-cancel]').onclick=()=>d.close();d.querySelector('[data-lantern-confirm]').onclick=()=>{d.close();run(fn,'#lantern-title');};d.addEventListener('close',()=>d.remove());};
 root.querySelectorAll('[data-lantern-start]').forEach(b=>b.onclick=()=>run(()=>startLantern(state,b.dataset.lanternStart,canExport),'#lantern-title'));
 root.querySelectorAll('[data-lantern-page]').forEach(b=>b.onclick=()=>run(()=>editLantern(state,'page',null,b.dataset.lanternPage,canExport),'#lantern-title'));
 root.querySelectorAll('[data-lantern-zero]').forEach(b=>b.onclick=()=>run(()=>editLantern(state,'zero',b.dataset.lanternZero,null,canExport),`[data-lantern-zero="${b.dataset.lanternZero}"]`));
 root.querySelectorAll('[data-lantern-move]').forEach(b=>b.onclick=()=>{const key=b.dataset.lanternMove,delta=Number(b.dataset.delta);if(run(()=>editLantern(state,'move',key,delta,canExport))){const forward=`[data-lantern-move="${key}"][data-delta="${delta}"]`,reverse=`[data-lantern-move="${key}"][data-delta="${-delta}"]`;focus(document.querySelector(forward)?.disabled?reverse:forward);}});
 root.querySelectorAll('[data-lantern-choice]').forEach(b=>b.onclick=()=>run(()=>editLantern(state,'choice',null,b.dataset.lanternChoice||null,canExport),`[data-lantern-choice="${b.dataset.lanternChoice}"]`));
 root.querySelectorAll('[data-lantern-guide]').forEach(b=>b.onclick=()=>run(()=>editLantern(state,'guide',null,b.dataset.lanternGuide||null,canExport),`[data-lantern-guide="${b.dataset.lanternGuide}"]`));
 root.querySelector('[data-lantern-check]')?.addEventListener('click',()=>run(()=>checkLantern(state,canExport),'#lantern-feedback'));
 root.querySelector('[data-lantern-keep]')?.addEventListener('click',()=>{if(!live())return;const v=lanternView(state);if(v.keptUnreadable){notice('The earlier kept version stays in notes. Start a separate lantern notebook to keep another version.');return;}if(v.work.kept!==null)confirm(false,()=>keepLantern(state,true,canExport));else run(()=>keepLantern(state,false,canExport),'#lantern-status','This version is kept.');});
 root.querySelectorAll('[data-lantern-recover]').forEach(b=>b.onclick=()=>confirm(true,()=>recoverLantern(state,canExport)));
 const support=(kind,event)=>{if(!live())return false;if(!supportLantern(state,kind,canExport)){notice(refusal);event?.stopImmediatePropagation();return false;}save();root.querySelector('#lantern-feedback')?.remove();return true;};
 root.querySelector('.lantern-help')?.addEventListener('toggle',e=>{if(e.target.open)support('help',e);});
 root.querySelector('.lantern-example')?.addEventListener('toggle',e=>{if(e.target.open)support('example',e);});
 root.querySelector('[data-lantern-together]')?.addEventListener('click',e=>{if(support('together',e))notice('Working together is recorded.');});
 root.querySelector('[data-speak]')?.addEventListener('click',e=>{if(!live()){e.stopImmediatePropagation();return;}e.currentTarget.dataset.speak=narration(lanternView(state));support('narrationRequested',e);});
}
